MODULE_SOURCES = {
    'galaxy_v1': '"""\ngalaxy_v0.py — Galaxy Sounds basket trader\n\nNo basket/spread structure: returns correlations within Galaxy Sounds are\nall ~0. Same situation as sleep pods — 5 independent products.\n\nBut unlike sleep pods, only 2 of these 5 are tradeable as mean reverters:\n\nTIER 1 — Mean reversion + MM (long EMA, trust prior):\n  - GALAXY_SOUNDS_DARK_MATTER   drift 0.34%, ADF max 0.50 (stable!)\n  - GALAXY_SOUNDS_SOLAR_FLAMES  drift 1.56%, ADF min 0.25 (most stationary)\n\nTIER 2 — MM-only (no directional signal, just collect spread):\n  - GALAXY_SOUNDS_PLANETARY_RINGS  drift 6.6%, ADF p=0.98 d2 (random walk)\n  - GALAXY_SOUNDS_SOLAR_WINDS      drift 8.6%, ADF max 0.72\n  - GALAXY_SOUNDS_BLACK_HOLES      drift 18%, never stationary\n\nSpreads $13-15 — wider than sleep pods. MM economics are good per fill\nbut fills will be rarer.\n"""\n\nfrom datamodel import OrderDepth, TradingState, Order\nfrom dataclasses import dataclass\nfrom typing import List, Dict, Any\nimport json\nimport math\n\n\nPOSITION_LIMIT = 10\n\n\n# ============================================================================\n# State management\n# ============================================================================\n\nclass SavedState:\n    def __init__(self, data: Dict[str, Any] = None):\n        self.data = data or {}\n\n    @staticmethod\n    def load(s: str) -> "SavedState":\n        if not s:\n            return SavedState()\n        try:\n            return SavedState(json.loads(s))\n        except Exception:\n            return SavedState()\n\n    def get(self, key: str) -> Dict[str, Any]:\n        return self.data.setdefault(key, {})\n\n    def put(self, key: str, value: Dict[str, Any]):\n        self.data[key] = value\n\n    def dump(self) -> str:\n        return json.dumps(self.data)\n\n\n# ============================================================================\n# Utilities\n# ============================================================================\n\ndef best_bid_ask_mid(order_depth: OrderDepth):\n    if not order_depth.buy_orders or not order_depth.sell_orders:\n        return None, None, None\n    best_bid = max(order_depth.buy_orders.keys())\n    best_ask = min(order_depth.sell_orders.keys())\n    return best_bid, best_ask, (best_bid + best_ask) / 2.0\n\n\ndef take_liquidity_buy(product: str, order_depth: OrderDepth,\n                       max_qty: int) -> List[Order]:\n    orders = []\n    remaining = max_qty\n    for ask_price in sorted(order_depth.sell_orders.keys()):\n        if remaining <= 0:\n            break\n        ask_vol = abs(order_depth.sell_orders[ask_price])\n        fill = min(ask_vol, remaining)\n        if fill > 0:\n            orders.append(Order(product, ask_price, int(fill)))\n            remaining -= fill\n    return orders\n\n\ndef take_liquidity_sell(product: str, order_depth: OrderDepth,\n                        max_qty: int) -> List[Order]:\n    orders = []\n    remaining = max_qty\n    for bid_price in sorted(order_depth.buy_orders.keys(), reverse=True):\n        if remaining <= 0:\n            break\n        bid_vol = order_depth.buy_orders[bid_price]\n        fill = min(bid_vol, remaining)\n        if fill > 0:\n            orders.append(Order(product, bid_price, int(-fill)))\n            remaining -= fill\n    return orders\n\n\n# ============================================================================\n# EMA helpers\n# ============================================================================\n\ndef update_ema(state: dict, value: float, alpha: float):\n    if not state.get("initialized", False):\n        state["ema_mean"] = value\n        state["ema_var"] = state.get("ema_var", 1.0)\n        state["initialized"] = True\n        state["n_ticks"] = state.get("n_ticks", 0) + 1\n        state["last_value"] = value\n        return\n    old_mean = state["ema_mean"]\n    diff = value - old_mean\n    state["ema_var"] = (1 - alpha) * (state["ema_var"] + alpha * diff * diff)\n    state["ema_mean"] = old_mean + alpha * diff\n    state["n_ticks"] += 1\n    state["last_value"] = value\n\n\ndef compute_z_blended(state: dict, prior_mean: float, prior_std: float,\n                      alpha: float) -> float:\n    std_emp = math.sqrt(max(state["ema_var"], 1.0))\n    warmup_target = 3.0 / alpha\n    blend = min(1.0, state["n_ticks"] / warmup_target)\n    std = blend * std_emp + (1 - blend) * prior_std\n    mean = blend * state["ema_mean"] + (1 - blend) * prior_mean\n    if std <= 0:\n        return 0.0\n    return (state["last_value"] - mean) / std\n\n\ndef z_to_magnitude(z: float, z_min: float, z_full: float) -> int:\n    abs_z = abs(z)\n    if abs_z <= z_min:\n        return 0\n    if abs_z >= z_full:\n        return POSITION_LIMIT\n    scale = (abs_z - z_min) / (z_full - z_min)\n    return int(round(POSITION_LIMIT * scale))\n\n\ndef execute_leg_capped(product: str, depth: OrderDepth,\n                       best_bid: int, best_ask: int,\n                       target_pos: int, current_pos: int,\n                       cross_allowed: bool,\n                       my_orders: Dict[str, List[Order]],\n                       mm_base_size: int = 3,\n                       mm_max_deviation: int = 2,\n                       cross_min_gap: int = 5):\n    """Mean reversion + MM-at-target. Used for Tier 1 products."""\n    buy_cap = max(0, POSITION_LIMIT - current_pos)\n    sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n    gap = target_pos - current_pos\n    bid_price = best_bid + 1 if (best_ask - best_bid) > 1 else best_bid\n    ask_price = best_ask - 1 if (best_ask - best_bid) > 1 else best_ask\n\n    my_buy_qty = 0\n    my_sell_qty = 0\n\n    if gap > 0:\n        qty_wanted = min(gap, buy_cap)\n        if cross_allowed and abs(gap) >= cross_min_gap and qty_wanted > 0:\n            taken = take_liquidity_buy(product, depth, qty_wanted)\n            taken_qty = sum(o.quantity for o in taken)\n            if taken_qty > buy_cap:\n                cap_remaining = buy_cap\n                fixed = []\n                for o in taken:\n                    if cap_remaining <= 0:\n                        break\n                    q = min(o.quantity, cap_remaining)\n                    fixed.append(Order(product, o.price, int(q)))\n                    cap_remaining -= q\n                taken = fixed\n                taken_qty = sum(o.quantity for o in taken)\n            my_orders.setdefault(product, []).extend(taken)\n            buy_cap -= taken_qty\n            qty_wanted -= taken_qty\n        if qty_wanted > 0 and buy_cap > 0:\n            my_buy_qty = min(qty_wanted, buy_cap)\n            buy_cap -= my_buy_qty\n    elif gap < 0:\n        qty_wanted = min(-gap, sell_cap)\n        if cross_allowed and abs(gap) >= cross_min_gap and qty_wanted > 0:\n            taken = take_liquidity_sell(product, depth, qty_wanted)\n            taken_qty = sum(-o.quantity for o in taken)\n            if taken_qty > sell_cap:\n                cap_remaining = sell_cap\n                fixed = []\n                for o in taken:\n                    if cap_remaining <= 0:\n                        break\n                    q = min(-o.quantity, cap_remaining)\n                    fixed.append(Order(product, o.price, int(-q)))\n                    cap_remaining -= q\n                taken = fixed\n                taken_qty = sum(-o.quantity for o in taken)\n            my_orders.setdefault(product, []).extend(taken)\n            sell_cap -= taken_qty\n            qty_wanted -= taken_qty\n        if qty_wanted > 0 and sell_cap > 0:\n            my_sell_qty = min(qty_wanted, sell_cap)\n            sell_cap -= my_sell_qty\n\n    target_drift_max = target_pos + mm_max_deviation\n    target_drift_min = target_pos - mm_max_deviation\n\n    mm_buy_room = target_drift_max - current_pos - my_buy_qty\n    mm_buy_qty = min(mm_base_size, max(0, mm_buy_room), buy_cap)\n\n    mm_sell_room = (current_pos - my_sell_qty) - target_drift_min\n    mm_sell_qty = min(mm_base_size, max(0, mm_sell_room), sell_cap)\n\n    total_buy_qty = my_buy_qty + mm_buy_qty\n    total_sell_qty = my_sell_qty + mm_sell_qty\n\n    max_total_buy = POSITION_LIMIT - current_pos\n    if total_buy_qty > max_total_buy:\n        total_buy_qty = max(0, max_total_buy)\n    max_total_sell = POSITION_LIMIT + current_pos\n    if total_sell_qty > max_total_sell:\n        total_sell_qty = max(0, max_total_sell)\n\n    if total_buy_qty > 0 and total_sell_qty > 0:\n        if bid_price >= ask_price:\n            if my_buy_qty > my_sell_qty:\n                total_sell_qty = 0\n            else:\n                total_buy_qty = 0\n\n    if total_buy_qty > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(bid_price), int(total_buy_qty))\n        )\n    if total_sell_qty > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(ask_price), int(-total_sell_qty))\n        )\n\n\ndef execute_mm_only(product: str, depth: OrderDepth,\n                    best_bid: int, best_ask: int,\n                    current_pos: int,\n                    my_orders: Dict[str, List[Order]],\n                    mm_base_size: int = 3,\n                    inventory_skew_max: int = 5):\n    """Pure MM with inventory skew — no directional signal.\n    \n    Quote bid+1/ask-1 (or join if spread is 1).\n    Inventory skew: when long, lean toward selling more (smaller buy size,\n    larger sell size); when short, lean toward buying more.\n    \n    This avoids directional bias from any signal — we simply collect spread\n    on every wiggle and gently target zero inventory.\n    """\n    buy_cap = max(0, POSITION_LIMIT - current_pos)\n    sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n    bid_price = best_bid + 1 if (best_ask - best_bid) > 1 else best_bid\n    ask_price = best_ask - 1 if (best_ask - best_bid) > 1 else best_ask\n\n    # Inventory skew: clamp to [-1, +1]\n    # When current_pos > 0 (long), reduce buy size, keep sell size\n    # When current_pos < 0 (short), keep buy size, reduce sell size\n    pos_pct = max(-1.0, min(1.0, current_pos / inventory_skew_max))\n\n    # Buy size shrinks as we get longer\n    buy_size = int(mm_base_size * (1.0 - max(0, pos_pct)))\n    # Sell size shrinks as we get shorter\n    sell_size = int(mm_base_size * (1.0 + min(0, pos_pct)))\n\n    buy_size = min(buy_size, buy_cap)\n    sell_size = min(sell_size, sell_cap)\n\n    if buy_size > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(bid_price), int(buy_size))\n        )\n    if sell_size > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(ask_price), int(-sell_size))\n        )\n\n\n# ============================================================================\n# Strategy\n# ============================================================================\n\n@dataclass\nclass MeanRevConfig:\n    """Tier 1: full mean reversion with z-score + MM-at-target."""\n    product: str\n    prior_mean: float\n    prior_std: float\n    ema_alpha: float\n    z_entry_min: float\n    z_entry_full: float\n    z_take_threshold: float\n\n\n@dataclass\nclass MMOnlyConfig:\n    """Tier 2: pure passive MM, no directional signal."""\n    product: str\n    mm_base_size: int = 3\n    inventory_skew_max: int = 5\n\n\n# Tier 1: stable mean reverters. Long EMA, trust prior.\nTIER_1_CONFIGS = [\n    MeanRevConfig(\n        product="GALAXY_SOUNDS_DARK_MATTER",\n        prior_mean=10227.0,    # avg of d2/d3/d4 (drifts only 0.34%)\n        prior_std=330.0,       # daily std ~330\n        ema_alpha=1.0 / 1500,  # long EMA - prior is reliable\n        z_entry_min=0.3,\n        z_entry_full=1.0,\n        z_take_threshold=2.0,\n    ),\n    MeanRevConfig(\n        product="GALAXY_SOUNDS_SOLAR_FLAMES",\n        prior_mean=11093.0,\n        prior_std=450.0,\n        ema_alpha=1.0 / 1500,\n        z_entry_min=0.5,\n        z_entry_full=1.5,\n        z_take_threshold=2.5,\n    ),\n]\n\n# Tier 2: pure MM. No directional signal — just collect spread.\nTIER_2_CONFIGS = [\n    # MMOnlyConfig(product="GALAXY_SOUNDS_PLANETARY_RINGS", mm_base_size=5, inventory_skew_max=7),\n    # MMOnlyConfig(product="GALAXY_SOUNDS_SOLAR_WINDS", mm_base_size=4, inventory_skew_max=5),\n    # MMOnlyConfig(product="GALAXY_SOUNDS_BLACK_HOLES", mm_base_size=5, inventory_skew_max=5),\n]\n\n\nclass GalaxySoundsStrategy:\n    name = "galaxy_v0"\n\n    @property\n    def products(self):\n        return ([c.product for c in TIER_1_CONFIGS]\n                + [c.product for c in TIER_2_CONFIGS])\n\n    def init_state(self, my_state: Dict[str, Any]):\n        my_state.setdefault("products", {})\n        for cfg in TIER_1_CONFIGS:\n            if cfg.product not in my_state["products"]:\n                my_state["products"][cfg.product] = {\n                    "ema_mean": cfg.prior_mean,\n                    "ema_var": cfg.prior_std ** 2,\n                    "initialized": False,\n                    "n_ticks": 0,\n                    "last_value": cfg.prior_mean,\n                }\n        # Tier 2 needs no state (stateless MM)\n\n    def run(self, state: TradingState, my_state: Dict[str, Any],\n            my_orders: Dict[str, List[Order]]) -> None:\n        self.init_state(my_state)\n        for cfg in TIER_1_CONFIGS:\n            self._run_meanrev(state, my_state, my_orders, cfg)\n        for cfg in TIER_2_CONFIGS:\n            self._run_mm_only(state, my_orders, cfg)\n\n    def _run_meanrev(self, state: TradingState, my_state: Dict[str, Any],\n                     my_orders: Dict[str, List[Order]], cfg: MeanRevConfig):\n        if cfg.product not in state.order_depths:\n            return\n        depth = state.order_depths[cfg.product]\n        bb, ba, mid = best_bid_ask_mid(depth)\n        if mid is None:\n            return\n\n        p_state = my_state["products"][cfg.product]\n        update_ema(p_state, mid, cfg.ema_alpha)\n        z = compute_z_blended(p_state, cfg.prior_mean, cfg.prior_std, cfg.ema_alpha)\n        magnitude = z_to_magnitude(z, cfg.z_entry_min, cfg.z_entry_full)\n\n        if z > 0:\n            target_pos = -magnitude\n        elif z < 0:\n            target_pos = +magnitude\n        else:\n            target_pos = 0\n\n        cross_allowed = abs(z) >= cfg.z_take_threshold\n\n        execute_leg_capped(cfg.product, depth, bb, ba, target_pos,\n                           state.position.get(cfg.product, 0),\n                           cross_allowed, my_orders)\n\n        short = "DAR" if "DARK" in cfg.product else "SOL_F"\n        print(f"[gs:T1:{short}] mid={mid:.0f} ema={p_state[\'ema_mean\']:.0f} "\n              f"z={z:+.2f} mag={magnitude} tgt={target_pos} "\n              f"pos={state.position.get(cfg.product, 0)}")\n\n    def _run_mm_only(self, state: TradingState,\n                     my_orders: Dict[str, List[Order]], cfg: MMOnlyConfig):\n        if cfg.product not in state.order_depths:\n            return\n        depth = state.order_depths[cfg.product]\n        bb, ba, mid = best_bid_ask_mid(depth)\n        if mid is None:\n            return\n\n        execute_mm_only(cfg.product, depth, bb, ba,\n                        state.position.get(cfg.product, 0),\n                        my_orders, cfg.mm_base_size, cfg.inventory_skew_max)\n\n        if "PLANETARY" in cfg.product:\n            short = "PLA"\n        elif "WINDS" in cfg.product:\n            short = "SOL_W"\n        else:\n            short = "BLA"\n        print(f"[gs:T2:{short}] mid={mid:.0f} pos={state.position.get(cfg.product, 0)} "\n              f"bid={bb} ask={ba}")\n\n\n# ============================================================================\n# Trader\n# ============================================================================\n\nclass Trader:\n    def __init__(self):\n        self.strategies = [GalaxySoundsStrategy()]\n\n    def run(self, state: TradingState):\n        saved = SavedState.load(state.traderData)\n        my_orders: Dict[str, List[Order]] = {}\n\n        for strat in self.strategies:\n            strat_state = saved.get(strat.name)\n            try:\n                strat.run(state, strat_state, my_orders)\n            except Exception as e:\n                print(f"[ERR strategy={strat.name}] {e}")\n            saved.put(strat.name, strat_state)\n\n        # Per-product cap aggregation\n        clean_orders = {}\n        for product, orders in my_orders.items():\n            current_pos = state.position.get(product, 0)\n            buy_cap = max(0, POSITION_LIMIT - current_pos)\n            sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n            buys = sorted([o for o in orders if o.quantity > 0], key=lambda o: o.price)\n            sells = sorted([o for o in orders if o.quantity < 0], key=lambda o: -o.price)\n\n            trimmed_buys = []\n            remaining = buy_cap\n            for o in buys:\n                if remaining <= 0:\n                    break\n                q = min(o.quantity, remaining)\n                if q > 0:\n                    trimmed_buys.append(Order(product, o.price, int(q)))\n                    remaining -= q\n\n            trimmed_sells = []\n            remaining = sell_cap\n            for o in sells:\n                if remaining <= 0:\n                    break\n                q = min(-o.quantity, remaining)\n                if q > 0:\n                    trimmed_sells.append(Order(product, o.price, int(-q)))\n                    remaining -= q\n\n            combined = trimmed_buys + trimmed_sells\n\n            if trimmed_buys and trimmed_sells:\n                min_sell_price = min(o.price for o in trimmed_sells)\n                combined = [o for o in combined\n                            if not (o.quantity > 0 and o.price >= min_sell_price)]\n\n            clean_orders[product] = combined\n\n        return clean_orders, 0, saved.dump()',
    'sleep_v2': '"""\nsleep_v2.py — Sleep Pods two-tier strategy\n\nv0/v1 lesson: only NYLON had a clean PnL curve. The other 4 pods drift\n16-20% across days, so mean reversion catches the wrong side of regime\nchanges. They make money eventually but with painful drawdowns.\n\nv2 strategy: split into two tiers like galaxy_v0 / translator_v0.\n\nTIER 1 — Mean reversion + MM (the only stable pod):\n  - SLEEP_POD_NYLON   drift -1% (most stable in category)\n\nTIER 2 — MM-only (4 drifty pods, just collect spread):\n  - SLEEP_POD_LAMB_WOOL  drift 0.84% but mean rev was flat\n  - SLEEP_POD_POLYESTER  drift +19.75%\n  - SLEEP_POD_SUEDE      drift +17%\n  - SLEEP_POD_COTTON     drift +16%\n\nSpreads ~$8-10 — wider than robots, similar to translators. MM-only with\ninventory skew should generate steady passive PnL without directional risk.\n\nNYLON params from v1 grid winner (already optimized).\nMM-only params start at sensible defaults (mm_base_size=3, skew_max=5),\ncan be grid searched after.\n"""\n\nfrom datamodel import OrderDepth, TradingState, Order\nfrom dataclasses import dataclass\nfrom typing import List, Dict, Any\nimport json\nimport math\n\n\nPOSITION_LIMIT = 10\n\n\n# ============================================================================\n# State management\n# ============================================================================\n\nclass SavedState:\n    def __init__(self, data: Dict[str, Any] = None):\n        self.data = data or {}\n\n    @staticmethod\n    def load(s: str) -> "SavedState":\n        if not s:\n            return SavedState()\n        try:\n            return SavedState(json.loads(s))\n        except Exception:\n            return SavedState()\n\n    def get(self, key: str) -> Dict[str, Any]:\n        return self.data.setdefault(key, {})\n\n    def put(self, key: str, value: Dict[str, Any]):\n        self.data[key] = value\n\n    def dump(self) -> str:\n        return json.dumps(self.data)\n\n\n# ============================================================================\n# Utilities\n# ============================================================================\n\ndef best_bid_ask_mid(order_depth: OrderDepth):\n    if not order_depth.buy_orders or not order_depth.sell_orders:\n        return None, None, None\n    best_bid = max(order_depth.buy_orders.keys())\n    best_ask = min(order_depth.sell_orders.keys())\n    return best_bid, best_ask, (best_bid + best_ask) / 2.0\n\n\ndef take_liquidity_buy(product: str, order_depth: OrderDepth,\n                       max_qty: int) -> List[Order]:\n    orders = []\n    remaining = max_qty\n    for ask_price in sorted(order_depth.sell_orders.keys()):\n        if remaining <= 0:\n            break\n        ask_vol = abs(order_depth.sell_orders[ask_price])\n        fill = min(ask_vol, remaining)\n        if fill > 0:\n            orders.append(Order(product, ask_price, int(fill)))\n            remaining -= fill\n    return orders\n\n\ndef take_liquidity_sell(product: str, order_depth: OrderDepth,\n                        max_qty: int) -> List[Order]:\n    orders = []\n    remaining = max_qty\n    for bid_price in sorted(order_depth.buy_orders.keys(), reverse=True):\n        if remaining <= 0:\n            break\n        bid_vol = order_depth.buy_orders[bid_price]\n        fill = min(bid_vol, remaining)\n        if fill > 0:\n            orders.append(Order(product, bid_price, int(-fill)))\n            remaining -= fill\n    return orders\n\n\n# ============================================================================\n# EMA helpers\n# ============================================================================\n\ndef update_ema(state: dict, value: float, alpha: float):\n    if not state.get("initialized", False):\n        state["ema_mean"] = value\n        state["ema_var"] = state.get("ema_var", 1.0)\n        state["initialized"] = True\n        state["n_ticks"] = state.get("n_ticks", 0) + 1\n        state["last_value"] = value\n        return\n    old_mean = state["ema_mean"]\n    diff = value - old_mean\n    state["ema_var"] = (1 - alpha) * (state["ema_var"] + alpha * diff * diff)\n    state["ema_mean"] = old_mean + alpha * diff\n    state["n_ticks"] += 1\n    state["last_value"] = value\n\n\ndef compute_z_blended(state: dict, prior_mean: float, prior_std: float,\n                      alpha: float) -> float:\n    std_emp = math.sqrt(max(state["ema_var"], 1.0))\n    warmup_target = 3.0 / alpha\n    blend = min(1.0, state["n_ticks"] / warmup_target)\n    std = blend * std_emp + (1 - blend) * prior_std\n    mean = blend * state["ema_mean"] + (1 - blend) * prior_mean\n    if std <= 0:\n        return 0.0\n    return (state["last_value"] - mean) / std\n\n\ndef z_to_magnitude(z: float, z_min: float, z_full: float) -> int:\n    abs_z = abs(z)\n    if abs_z <= z_min:\n        return 0\n    if abs_z >= z_full:\n        return POSITION_LIMIT\n    scale = (abs_z - z_min) / (z_full - z_min)\n    return int(round(POSITION_LIMIT * scale))\n\n\ndef execute_leg_capped(product: str, depth: OrderDepth,\n                       best_bid: int, best_ask: int,\n                       target_pos: int, current_pos: int,\n                       cross_allowed: bool,\n                       my_orders: Dict[str, List[Order]],\n                       mm_base_size: int = 2,\n                       mm_max_deviation: int = 3,\n                       cross_min_gap: int = 5):\n    """Mean reversion + MM-at-target. Used for Tier 1 (NYLON only)."""\n    buy_cap = max(0, POSITION_LIMIT - current_pos)\n    sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n    gap = target_pos - current_pos\n    bid_price = best_bid + 1 if (best_ask - best_bid) > 1 else best_bid\n    ask_price = best_ask - 1 if (best_ask - best_bid) > 1 else best_ask\n\n    my_buy_qty = 0\n    my_sell_qty = 0\n\n    if gap > 0:\n        qty_wanted = min(gap, buy_cap)\n        if cross_allowed and abs(gap) >= cross_min_gap and qty_wanted > 0:\n            taken = take_liquidity_buy(product, depth, qty_wanted)\n            taken_qty = sum(o.quantity for o in taken)\n            if taken_qty > buy_cap:\n                cap_remaining = buy_cap\n                fixed = []\n                for o in taken:\n                    if cap_remaining <= 0:\n                        break\n                    q = min(o.quantity, cap_remaining)\n                    fixed.append(Order(product, o.price, int(q)))\n                    cap_remaining -= q\n                taken = fixed\n                taken_qty = sum(o.quantity for o in taken)\n            my_orders.setdefault(product, []).extend(taken)\n            buy_cap -= taken_qty\n            qty_wanted -= taken_qty\n        if qty_wanted > 0 and buy_cap > 0:\n            my_buy_qty = min(qty_wanted, buy_cap)\n            buy_cap -= my_buy_qty\n    elif gap < 0:\n        qty_wanted = min(-gap, sell_cap)\n        if cross_allowed and abs(gap) >= cross_min_gap and qty_wanted > 0:\n            taken = take_liquidity_sell(product, depth, qty_wanted)\n            taken_qty = sum(-o.quantity for o in taken)\n            if taken_qty > sell_cap:\n                cap_remaining = sell_cap\n                fixed = []\n                for o in taken:\n                    if cap_remaining <= 0:\n                        break\n                    q = min(-o.quantity, cap_remaining)\n                    fixed.append(Order(product, o.price, int(-q)))\n                    cap_remaining -= q\n                taken = fixed\n                taken_qty = sum(-o.quantity for o in taken)\n            my_orders.setdefault(product, []).extend(taken)\n            sell_cap -= taken_qty\n            qty_wanted -= taken_qty\n        if qty_wanted > 0 and sell_cap > 0:\n            my_sell_qty = min(qty_wanted, sell_cap)\n            sell_cap -= my_sell_qty\n\n    target_drift_max = target_pos + mm_max_deviation\n    target_drift_min = target_pos - mm_max_deviation\n\n    mm_buy_room = target_drift_max - current_pos - my_buy_qty\n    mm_buy_qty = min(mm_base_size, max(0, mm_buy_room), buy_cap)\n\n    mm_sell_room = (current_pos - my_sell_qty) - target_drift_min\n    mm_sell_qty = min(mm_base_size, max(0, mm_sell_room), sell_cap)\n\n    total_buy_qty = my_buy_qty + mm_buy_qty\n    total_sell_qty = my_sell_qty + mm_sell_qty\n\n    max_total_buy = POSITION_LIMIT - current_pos\n    if total_buy_qty > max_total_buy:\n        total_buy_qty = max(0, max_total_buy)\n    max_total_sell = POSITION_LIMIT + current_pos\n    if total_sell_qty > max_total_sell:\n        total_sell_qty = max(0, max_total_sell)\n\n    if total_buy_qty > 0 and total_sell_qty > 0:\n        if bid_price >= ask_price:\n            if my_buy_qty > my_sell_qty:\n                total_sell_qty = 0\n            else:\n                total_buy_qty = 0\n\n    if total_buy_qty > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(bid_price), int(total_buy_qty))\n        )\n    if total_sell_qty > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(ask_price), int(-total_sell_qty))\n        )\n\n\ndef execute_mm_only(product: str, depth: OrderDepth,\n                    best_bid: int, best_ask: int,\n                    current_pos: int,\n                    my_orders: Dict[str, List[Order]],\n                    mm_base_size: int = 3,\n                    inventory_skew_max: int = 5):\n    """Pure MM with inventory skew — no directional signal."""\n    buy_cap = max(0, POSITION_LIMIT - current_pos)\n    sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n    bid_price = best_bid + 1 if (best_ask - best_bid) > 1 else best_bid\n    ask_price = best_ask - 1 if (best_ask - best_bid) > 1 else best_ask\n\n    pos_pct = max(-1.0, min(1.0, current_pos / inventory_skew_max))\n\n    buy_size = int(mm_base_size * (1.0 - max(0, pos_pct)))\n    sell_size = int(mm_base_size * (1.0 + min(0, pos_pct)))\n\n    buy_size = min(buy_size, buy_cap)\n    sell_size = min(sell_size, sell_cap)\n\n    if buy_size > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(bid_price), int(buy_size))\n        )\n    if sell_size > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(ask_price), int(-sell_size))\n        )\n\n\n# ============================================================================\n# Strategy\n# ============================================================================\n\n@dataclass\nclass MeanRevConfig:\n    product: str\n    prior_mean: float\n    prior_std: float\n    ema_alpha: float\n    z_entry_min: float\n    z_entry_full: float\n    z_take_threshold: float\n\n\n@dataclass\nclass MMOnlyConfig:\n    product: str\n    mm_base_size: int = 3\n    inventory_skew_max: int = 5\n\n\n# Tier 1: NYLON only — params from v1 grid winner\nTIER_1_CONFIGS = [\n    MeanRevConfig(\n        product="SLEEP_POD_NYLON",\n        prior_mean=9636.0,\n        prior_std=200.0,\n        ema_alpha=1.0 / 1000,\n        z_entry_min=0.3,\n        z_entry_full=1.0,\n        z_take_threshold=2.5,\n    ),\n]\n\n# Tier 2: 4 (now 3) drifty pods, MM-only\nTIER_2_CONFIGS = [\n    MMOnlyConfig(product="SLEEP_POD_POLYESTER"),\n    MMOnlyConfig(product="SLEEP_POD_SUEDE"),\n    MMOnlyConfig(product="SLEEP_POD_COTTON"),\n]\n\n\nclass SleepPodStrategy:\n    name = "sleep_v2"\n\n    @property\n    def products(self):\n        return ([c.product for c in TIER_1_CONFIGS]\n                + [c.product for c in TIER_2_CONFIGS])\n\n    def init_state(self, my_state: Dict[str, Any]):\n        my_state.setdefault("products", {})\n        for cfg in TIER_1_CONFIGS:\n            if cfg.product not in my_state["products"]:\n                my_state["products"][cfg.product] = {\n                    "ema_mean": cfg.prior_mean,\n                    "ema_var": cfg.prior_std ** 2,\n                    "initialized": False,\n                    "n_ticks": 0,\n                    "last_value": cfg.prior_mean,\n                }\n\n    def run(self, state: TradingState, my_state: Dict[str, Any],\n            my_orders: Dict[str, List[Order]]) -> None:\n        self.init_state(my_state)\n        for cfg in TIER_1_CONFIGS:\n            self._run_meanrev(state, my_state, my_orders, cfg)\n        for cfg in TIER_2_CONFIGS:\n            self._run_mm_only(state, my_orders, cfg)\n\n    def _run_meanrev(self, state: TradingState, my_state: Dict[str, Any],\n                     my_orders: Dict[str, List[Order]], cfg: MeanRevConfig):\n        if cfg.product not in state.order_depths:\n            return\n        depth = state.order_depths[cfg.product]\n        bb, ba, mid = best_bid_ask_mid(depth)\n        if mid is None:\n            return\n\n        p_state = my_state["products"][cfg.product]\n        update_ema(p_state, mid, cfg.ema_alpha)\n        z = compute_z_blended(p_state, cfg.prior_mean, cfg.prior_std, cfg.ema_alpha)\n        magnitude = z_to_magnitude(z, cfg.z_entry_min, cfg.z_entry_full)\n\n        if z > 0:\n            target_pos = -magnitude\n        elif z < 0:\n            target_pos = +magnitude\n        else:\n            target_pos = 0\n\n        cross_allowed = abs(z) >= cfg.z_take_threshold\n\n        execute_leg_capped(cfg.product, depth, bb, ba, target_pos,\n                           state.position.get(cfg.product, 0),\n                           cross_allowed, my_orders)\n\n        print(f"[sl:T1:NYL] mid={mid:.0f} ema={p_state[\'ema_mean\']:.0f} "\n              f"z={z:+.2f} mag={magnitude} tgt={target_pos} "\n              f"pos={state.position.get(cfg.product, 0)}")\n\n    def _run_mm_only(self, state: TradingState,\n                     my_orders: Dict[str, List[Order]], cfg: MMOnlyConfig):\n        if cfg.product not in state.order_depths:\n            return\n        depth = state.order_depths[cfg.product]\n        bb, ba, mid = best_bid_ask_mid(depth)\n        if mid is None:\n            return\n\n        execute_mm_only(cfg.product, depth, bb, ba,\n                        state.position.get(cfg.product, 0),\n                        my_orders, cfg.mm_base_size, cfg.inventory_skew_max)\n\n        if "LAMB" in cfg.product:\n            short = "LAM"\n        elif "POLY" in cfg.product:\n            short = "POL"\n        elif "SUEDE" in cfg.product:\n            short = "SUE"\n        else:\n            short = "COT"\n        print(f"[sl:T2:{short}] mid={mid:.0f} pos={state.position.get(cfg.product, 0)} "\n              f"bid={bb} ask={ba}")\n\n\n# ============================================================================\n# Trader\n# ============================================================================\n\nclass Trader:\n    def __init__(self):\n        self.strategies = [SleepPodStrategy()]\n\n    def run(self, state: TradingState):\n        saved = SavedState.load(state.traderData)\n        my_orders: Dict[str, List[Order]] = {}\n\n        for strat in self.strategies:\n            strat_state = saved.get(strat.name)\n            try:\n                strat.run(state, strat_state, my_orders)\n            except Exception as e:\n                print(f"[ERR strategy={strat.name}] {e}")\n            saved.put(strat.name, strat_state)\n\n        clean_orders = {}\n        for product, orders in my_orders.items():\n            current_pos = state.position.get(product, 0)\n            buy_cap = max(0, POSITION_LIMIT - current_pos)\n            sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n            buys = sorted([o for o in orders if o.quantity > 0], key=lambda o: o.price)\n            sells = sorted([o for o in orders if o.quantity < 0], key=lambda o: -o.price)\n\n            trimmed_buys = []\n            remaining = buy_cap\n            for o in buys:\n                if remaining <= 0:\n                    break\n                q = min(o.quantity, remaining)\n                if q > 0:\n                    trimmed_buys.append(Order(product, o.price, int(q)))\n                    remaining -= q\n\n            trimmed_sells = []\n            remaining = sell_cap\n            for o in sells:\n                if remaining <= 0:\n                    break\n                q = min(-o.quantity, remaining)\n                if q > 0:\n                    trimmed_sells.append(Order(product, o.price, int(-q)))\n                    remaining -= q\n\n            combined = trimmed_buys + trimmed_sells\n\n            if trimmed_buys and trimmed_sells:\n                min_sell_price = min(o.price for o in trimmed_sells)\n                combined = [o for o in combined\n                            if not (o.quantity > 0 and o.price >= min_sell_price)]\n\n            clean_orders[product] = combined\n\n        return clean_orders, 0, saved.dump()',
    'snacks_v5': '"""\nsnacks_v4.py — Round 5 multi-strategy trader (v4 of snackpack basket strategy)\n\nChanges from v3:\n  1. Corrected priors. v3 used CHOC-VAN prior_mean=-100, but the actual\n     measured mean is -254 (CHOC ~9843, VAN ~10097). v3 took ~3000 ticks\n     to drift to true value, costing us PnL. v4 uses measured values.\n       - CHOC-VAN: mean=-254, std=65 (true σ of the difference)\n       - STRAW-RASP: mean=629, std=200\n  2. Faster STRAW-RASP EMA (1/500 → 1/300) since the regime drifts.\n  3. NEW: Standalone PIS (Pistachio) mean reverter.\n       - PIS doesn\'t have a stable partner relationship across days\n       - But it DOES mean-revert intraday (half-life ~850-1250 ticks)\n       - It drifts day-to-day (mean: 9655 → 9487 → 9344, ~-$100/day)\n       - Strategy: rolling EMA z-score on PIS alone, same hard-cap framework\n  4. PIS uses its own Strategy class. Modular — same interface.\n\nPnL expectation: CHOC/VAN/STRAW/RASP ≈ same as v3. PIS is a small bonus\n($1k-3k per 3 days plausibly, given ~$130 daily std).\n"""\n\nfrom datamodel import OrderDepth, TradingState, Order\nfrom dataclasses import dataclass, asdict, field\nfrom typing import List, Dict, Any, Optional\nimport json\nimport math\n\n\nPOSITION_LIMIT = 10\n\n\n# ============================================================================\n# STATE MANAGEMENT\n# ============================================================================\n\nclass SavedState:\n    def __init__(self, data: Dict[str, Any] = None):\n        self.data = data or {}\n\n    @staticmethod\n    def load(s: str) -> "SavedState":\n        if not s:\n            return SavedState()\n        try:\n            return SavedState(json.loads(s))\n        except Exception:\n            return SavedState()\n\n    def get(self, key: str) -> Dict[str, Any]:\n        return self.data.setdefault(key, {})\n\n    def put(self, key: str, value: Dict[str, Any]):\n        self.data[key] = value\n\n    def dump(self) -> str:\n        return json.dumps(self.data)\n\n\n# ============================================================================\n# UTILITIES\n# ============================================================================\n\ndef best_bid_ask_mid(order_depth: OrderDepth):\n    if not order_depth.buy_orders or not order_depth.sell_orders:\n        return None, None, None\n    best_bid = max(order_depth.buy_orders.keys())\n    best_ask = min(order_depth.sell_orders.keys())\n    return best_bid, best_ask, (best_bid + best_ask) / 2.0\n\n\ndef order_book_imbalance_l1(order_depth: OrderDepth) -> float:\n    if not order_depth.buy_orders or not order_depth.sell_orders:\n        return 0.0\n    best_bid = max(order_depth.buy_orders.keys())\n    best_ask = min(order_depth.sell_orders.keys())\n    bv = order_depth.buy_orders[best_bid]\n    av = abs(order_depth.sell_orders[best_ask])\n    denom = bv + av\n    return (bv - av) / denom if denom > 0 else 0.0\n\n\ndef take_liquidity_buy(product: str, order_depth: OrderDepth,\n                       max_qty: int) -> List[Order]:\n    orders = []\n    remaining = max_qty\n    for ask_price in sorted(order_depth.sell_orders.keys()):\n        if remaining <= 0:\n            break\n        ask_vol = abs(order_depth.sell_orders[ask_price])\n        fill = min(ask_vol, remaining)\n        if fill > 0:\n            orders.append(Order(product, ask_price, int(fill)))\n            remaining -= fill\n    return orders\n\n\ndef take_liquidity_sell(product: str, order_depth: OrderDepth,\n                        max_qty: int) -> List[Order]:\n    orders = []\n    remaining = max_qty\n    for bid_price in sorted(order_depth.buy_orders.keys(), reverse=True):\n        if remaining <= 0:\n            break\n        bid_vol = order_depth.buy_orders[bid_price]\n        fill = min(bid_vol, remaining)\n        if fill > 0:\n            orders.append(Order(product, bid_price, int(-fill)))\n            remaining -= fill\n    return orders\n\n\n# ============================================================================\n# Shared helpers for EMA-based mean reversion\n# ============================================================================\n\ndef update_ema(state: dict, value: float, alpha: float):\n    """Online EMA mean+variance update. Initializes on first call."""\n    if not state.get("initialized", False):\n        state["ema_mean"] = value\n        state["ema_var"] = state.get("ema_var", 1.0)\n        state["initialized"] = True\n        state["n_ticks"] = state.get("n_ticks", 0) + 1\n        state["last_value"] = value\n        return\n    old_mean = state["ema_mean"]\n    diff = value - old_mean\n    state["ema_var"] = (1 - alpha) * (state["ema_var"] + alpha * diff * diff)\n    state["ema_mean"] = old_mean + alpha * diff\n    state["n_ticks"] += 1\n    state["last_value"] = value\n\n\ndef compute_z_blended(state: dict, prior_mean: float, prior_std: float,\n                      alpha: float) -> float:\n    """Z-score with prior blending during warmup."""\n    std_emp = math.sqrt(max(state["ema_var"], 1.0))\n    warmup_target = 3.0 / alpha\n    blend = min(1.0, state["n_ticks"] / warmup_target)\n    std = blend * std_emp + (1 - blend) * prior_std\n    mean = blend * state["ema_mean"] + (1 - blend) * prior_mean\n    if std <= 0:\n        return 0.0\n    return (state["last_value"] - mean) / std\n\n\ndef z_to_magnitude(z: float, z_min: float, z_full: float) -> int:\n    """|z|-to-position-magnitude in [0, POSITION_LIMIT]."""\n    abs_z = abs(z)\n    if abs_z <= z_min:\n        return 0\n    if abs_z >= z_full:\n        return POSITION_LIMIT\n    scale = (abs_z - z_min) / (z_full - z_min)\n    return int(round(POSITION_LIMIT * scale))\n\n\ndef execute_leg_capped(product: str, depth: OrderDepth,\n                       best_bid: int, best_ask: int,\n                       target_pos: int, current_pos: int,\n                       cross_allowed: bool,\n                       my_orders: Dict[str, List[Order]],\n                       mm_base_size: int = 1,\n                       mm_max_deviation: int = 4,\n                       cross_min_gap: int = 5):\n    """Single-leg order placement with hard position caps and MM-at-target.\n    Produces at most one buy and one sell per call. Used by both spread\n    strategy and standalone PIS strategy.\n    """\n    buy_cap = max(0, POSITION_LIMIT - current_pos)\n    sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n    gap = target_pos - current_pos\n\n    bid_price = best_bid + 1 if (best_ask - best_bid) > 1 else best_bid\n    ask_price = best_ask - 1 if (best_ask - best_bid) > 1 else best_ask\n\n    my_buy_qty = 0\n    my_sell_qty = 0\n\n    if gap > 0:\n        qty_wanted = min(gap, buy_cap)\n        if cross_allowed and abs(gap) >= cross_min_gap and qty_wanted > 0:\n            taken = take_liquidity_buy(product, depth, qty_wanted)\n            taken_qty = sum(o.quantity for o in taken)\n            if taken_qty > buy_cap:\n                cap_remaining = buy_cap\n                fixed = []\n                for o in taken:\n                    if cap_remaining <= 0:\n                        break\n                    q = min(o.quantity, cap_remaining)\n                    fixed.append(Order(product, o.price, int(q)))\n                    cap_remaining -= q\n                taken = fixed\n                taken_qty = sum(o.quantity for o in taken)\n            my_orders.setdefault(product, []).extend(taken)\n            buy_cap -= taken_qty\n            qty_wanted -= taken_qty\n        if qty_wanted > 0 and buy_cap > 0:\n            my_buy_qty = min(qty_wanted, buy_cap)\n            buy_cap -= my_buy_qty\n    elif gap < 0:\n        qty_wanted = min(-gap, sell_cap)\n        if cross_allowed and abs(gap) >= cross_min_gap and qty_wanted > 0:\n            taken = take_liquidity_sell(product, depth, qty_wanted)\n            taken_qty = sum(-o.quantity for o in taken)\n            if taken_qty > sell_cap:\n                cap_remaining = sell_cap\n                fixed = []\n                for o in taken:\n                    if cap_remaining <= 0:\n                        break\n                    q = min(-o.quantity, cap_remaining)\n                    fixed.append(Order(product, o.price, int(-q)))\n                    cap_remaining -= q\n                taken = fixed\n                taken_qty = sum(-o.quantity for o in taken)\n            my_orders.setdefault(product, []).extend(taken)\n            sell_cap -= taken_qty\n            qty_wanted -= taken_qty\n        if qty_wanted > 0 and sell_cap > 0:\n            my_sell_qty = min(qty_wanted, sell_cap)\n            sell_cap -= my_sell_qty\n\n    # MM-at-target: add passive quotes that won\'t push past target±MM_MAX_DEVIATION\n    target_drift_max = target_pos + mm_max_deviation\n    target_drift_min = target_pos - mm_max_deviation\n\n    mm_buy_room = target_drift_max - current_pos - my_buy_qty\n    mm_buy_qty = min(mm_base_size, max(0, mm_buy_room), buy_cap)\n\n    mm_sell_room = (current_pos - my_sell_qty) - target_drift_min\n    mm_sell_qty = min(mm_base_size, max(0, mm_sell_room), sell_cap)\n\n    total_buy_qty = my_buy_qty + mm_buy_qty\n    total_sell_qty = my_sell_qty + mm_sell_qty\n\n    max_total_buy = POSITION_LIMIT - current_pos\n    if total_buy_qty > max_total_buy:\n        total_buy_qty = max(0, max_total_buy)\n    max_total_sell = POSITION_LIMIT + current_pos\n    if total_sell_qty > max_total_sell:\n        total_sell_qty = max(0, max_total_sell)\n\n    if total_buy_qty > 0 and total_sell_qty > 0:\n        if bid_price >= ask_price:\n            if my_buy_qty > my_sell_qty:\n                total_sell_qty = 0\n            else:\n                total_buy_qty = 0\n\n    if total_buy_qty > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(bid_price), int(total_buy_qty))\n        )\n    if total_sell_qty > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(ask_price), int(-total_sell_qty))\n        )\n\n\n# ============================================================================\n# STRATEGY BASE\n# ============================================================================\n\nclass Strategy:\n    name: str = "base"\n    products: List[str] = []\n\n    def init_state(self, state: TradingState, my_state: Dict[str, Any]):\n        pass\n\n    def run(self, state: TradingState, my_state: Dict[str, Any],\n            my_orders: Dict[str, List[Order]]) -> None:\n        raise NotImplementedError\n\n\n# ============================================================================\n# SNACKPACK SPREAD STRATEGY (CHOC-VAN, STRAW-RASP)\n# ============================================================================\n\n@dataclass\nclass SpreadConfig:\n    leg_a: str\n    leg_b: str\n    prior_mean: float\n    prior_std: float\n    ema_alpha: float\n    z_entry_min: float\n    z_entry_full: float\n    z_take_threshold: float\n\n\nSPREAD_CONFIGS = [\n    # CHOC - VAN: very stable, but corrected priors based on actual data\n    # CHOC mean ≈ 9843, VAN mean ≈ 10097, so CHOC - VAN ≈ -254\n    # σ(CHOC+VAN) was 76 (sum); σ(CHOC-VAN) ≈ 2*σ_individual / sqrt(corr stuff)\n    # measured σ(CHOC-VAN) ≈ 65\n    SpreadConfig(\n        leg_a="SNACKPACK_CHOCOLATE",\n        leg_b="SNACKPACK_VANILLA",\n        prior_mean=-254.0,\n        prior_std=65.0,\n        ema_alpha=1.0 / 5000,\n        z_entry_min=0.1,\n        z_entry_full=0.7,\n        z_take_threshold=3.3,\n    ),\n    # STRAW - RASP: less stable, drifts more.\n    # STRAW mean ~10707, RASP mean ~10078, diff ≈ 629\n    # Measured σ ≈ 200 (will track via EMA so this prior less critical)\n    SpreadConfig(\n        leg_a="SNACKPACK_STRAWBERRY",\n        leg_b="SNACKPACK_RASPBERRY",\n        prior_mean=629.0,\n        prior_std=200.0,\n        ema_alpha=1.0 / 3000,    # was 1/500 — track drift faster\n        z_entry_min=0.5,\n        z_entry_full=0.7,\n        z_take_threshold=1.7,\n    ),\n]\n\n\nclass SnackpackSpreadStrategy(Strategy):\n    name = "snackpacks_spreads_v4"\n    products = [\n        "SNACKPACK_CHOCOLATE", "SNACKPACK_VANILLA",\n        "SNACKPACK_STRAWBERRY", "SNACKPACK_RASPBERRY",\n    ]\n\n    def init_state(self, state: TradingState, my_state: Dict[str, Any]):\n        my_state.setdefault("spreads", {})\n        for cfg in SPREAD_CONFIGS:\n            key = cfg.leg_a\n            if key not in my_state["spreads"]:\n                my_state["spreads"][key] = {\n                    "ema_mean": cfg.prior_mean,\n                    "ema_var": cfg.prior_std ** 2,\n                    "initialized": False,\n                    "n_ticks": 0,\n                    "last_value": cfg.prior_mean,\n                }\n\n    def run(self, state: TradingState, my_state: Dict[str, Any],\n            my_orders: Dict[str, List[Order]]) -> None:\n        self.init_state(state, my_state)\n        for cfg in SPREAD_CONFIGS:\n            self._run_spread(state, my_state, my_orders, cfg)\n\n    def _run_spread(self, state: TradingState, my_state: Dict[str, Any],\n                    my_orders: Dict[str, List[Order]], cfg: SpreadConfig):\n        if cfg.leg_a not in state.order_depths or cfg.leg_b not in state.order_depths:\n            return\n        depth_a = state.order_depths[cfg.leg_a]\n        depth_b = state.order_depths[cfg.leg_b]\n        bb_a, ba_a, mid_a = best_bid_ask_mid(depth_a)\n        bb_b, ba_b, mid_b = best_bid_ask_mid(depth_b)\n        if mid_a is None or mid_b is None:\n            return\n\n        spread_value = mid_a - mid_b\n        s_state = my_state["spreads"][cfg.leg_a]\n        update_ema(s_state, spread_value, cfg.ema_alpha)\n        z = compute_z_blended(s_state, cfg.prior_mean, cfg.prior_std, cfg.ema_alpha)\n        magnitude = z_to_magnitude(z, cfg.z_entry_min, cfg.z_entry_full)\n\n        if z > 0:\n            target_a = -magnitude\n            target_b = +magnitude\n        elif z < 0:\n            target_a = +magnitude\n            target_b = -magnitude\n        else:\n            target_a = 0\n            target_b = 0\n\n        cross_allowed = abs(z) >= cfg.z_take_threshold\n\n        execute_leg_capped(cfg.leg_a, depth_a, bb_a, ba_a, target_a,\n                           state.position.get(cfg.leg_a, 0),\n                           cross_allowed, my_orders)\n        execute_leg_capped(cfg.leg_b, depth_b, bb_b, ba_b, target_b,\n                           state.position.get(cfg.leg_b, 0),\n                           cross_allowed, my_orders)\n\n        a_short = cfg.leg_a.replace("SNACKPACK_", "")[:3]\n        b_short = cfg.leg_b.replace("SNACKPACK_", "")[:3]\n        print(f"[snack:{a_short}-{b_short}] spr={spread_value:+.0f} "\n              f"ema={s_state[\'ema_mean\']:+.0f} z={z:+.2f} mag={magnitude} "\n              f"tgt_a={target_a} tgt_b={target_b} "\n              f"pos_a={state.position.get(cfg.leg_a, 0)} "\n              f"pos_b={state.position.get(cfg.leg_b, 0)}")\n\n\n# ============================================================================\n# PISTACHIO STANDALONE STRATEGY\n# ============================================================================\n#\n# PIS doesn\'t have a stable partner relationship across days, but it DOES\n# mean-revert intraday (half-life ~850-1250 ticks). Daily mean drifts by\n# about $100/day so we need a rolling EMA, not a fixed fair value.\n#\n# Same z-score sizing framework as the spreads, just on a single product.\n# Daily std ≈ $130-145, so |z|=1 is about $130 from EMA mean.\n# ============================================================================\n\n@dataclass\nclass SoloConfig:\n    product: str\n    prior_mean: float\n    prior_std: float\n    ema_alpha: float\n    z_entry_min: float\n    z_entry_full: float\n    z_take_threshold: float\n\n\nSOLO_CONFIGS = [\n    # PIS: range ~$600/day around a slowly-drifting mean\n    # mean drifts: 9655 -> 9487 -> 9344 (about -$100/day)\n    # daily std: 144, 142, 127 (avg ~138)\n    # spread ~$16, so cross cost is meaningful\n    SoloConfig(\n        product="SNACKPACK_PISTACHIO",\n        prior_mean=9500.0,    # halfway through observed drift range\n        prior_std=140.0,\n        ema_alpha=1.0 / 500,  # track drift but smooth out noise\n        z_entry_min=0.1,\n        z_entry_full=0.7,\n        z_take_threshold=2.3,\n    ),\n]\n\n\nclass SolomeanReversionStrategy(Strategy):\n    """Generic individual-product mean reversion. Anyone can be added."""\n    name = "snackpacks_solo_v4"\n\n    @property\n    def products(self):\n        return [c.product for c in SOLO_CONFIGS]\n\n    def init_state(self, state: TradingState, my_state: Dict[str, Any]):\n        my_state.setdefault("products", {})\n        for cfg in SOLO_CONFIGS:\n            if cfg.product not in my_state["products"]:\n                my_state["products"][cfg.product] = {\n                    "ema_mean": cfg.prior_mean,\n                    "ema_var": cfg.prior_std ** 2,\n                    "initialized": False,\n                    "n_ticks": 0,\n                    "last_value": cfg.prior_mean,\n                }\n\n    def run(self, state: TradingState, my_state: Dict[str, Any],\n            my_orders: Dict[str, List[Order]]) -> None:\n        self.init_state(state, my_state)\n        for cfg in SOLO_CONFIGS:\n            self._run_solo(state, my_state, my_orders, cfg)\n\n    def _run_solo(self, state: TradingState, my_state: Dict[str, Any],\n                  my_orders: Dict[str, List[Order]], cfg: SoloConfig):\n        if cfg.product not in state.order_depths:\n            return\n        depth = state.order_depths[cfg.product]\n        bb, ba, mid = best_bid_ask_mid(depth)\n        if mid is None:\n            return\n\n        p_state = my_state["products"][cfg.product]\n        update_ema(p_state, mid, cfg.ema_alpha)\n        z = compute_z_blended(p_state, cfg.prior_mean, cfg.prior_std, cfg.ema_alpha)\n        magnitude = z_to_magnitude(z, cfg.z_entry_min, cfg.z_entry_full)\n\n        # z > 0: price > mean → expect reversion down → SHORT\n        # z < 0: price < mean → expect reversion up → LONG\n        if z > 0:\n            target_pos = -magnitude\n        elif z < 0:\n            target_pos = +magnitude\n        else:\n            target_pos = 0\n\n        cross_allowed = abs(z) >= cfg.z_take_threshold\n\n        execute_leg_capped(cfg.product, depth, bb, ba, target_pos,\n                           state.position.get(cfg.product, 0),\n                           cross_allowed, my_orders)\n\n        short_name = cfg.product.replace("SNACKPACK_", "")[:3]\n        print(f"[solo:{short_name}] mid={mid:.0f} ema={p_state[\'ema_mean\']:.0f} "\n              f"z={z:+.2f} mag={magnitude} tgt={target_pos} "\n              f"pos={state.position.get(cfg.product, 0)}")\n\n\n# ============================================================================\n# TRADER\n# ============================================================================\n\nclass Trader:\n    def __init__(self):\n        self.strategies: List[Strategy] = [\n            SnackpackSpreadStrategy(),\n            SolomeanReversionStrategy(),\n        ]\n\n    def run(self, state: TradingState):\n        saved = SavedState.load(state.traderData)\n        my_orders: Dict[str, List[Order]] = {}\n\n        for strat in self.strategies:\n            strat_state = saved.get(strat.name)\n            try:\n                strat.run(state, strat_state, my_orders)\n            except Exception as e:\n                print(f"[ERR strategy={strat.name}] {e}")\n            saved.put(strat.name, strat_state)\n\n        # Aggregate cap per product (final defense)\n        clean_orders = {}\n        for product, orders in my_orders.items():\n            current_pos = state.position.get(product, 0)\n            buy_cap = max(0, POSITION_LIMIT - current_pos)\n            sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n            buys = sorted([o for o in orders if o.quantity > 0], key=lambda o: o.price)\n            sells = sorted([o for o in orders if o.quantity < 0], key=lambda o: -o.price)\n\n            trimmed_buys = []\n            remaining = buy_cap\n            for o in buys:\n                if remaining <= 0:\n                    break\n                q = min(o.quantity, remaining)\n                if q > 0:\n                    trimmed_buys.append(Order(product, o.price, int(q)))\n                    remaining -= q\n\n            trimmed_sells = []\n            remaining = sell_cap\n            for o in sells:\n                if remaining <= 0:\n                    break\n                q = min(-o.quantity, remaining)\n                if q > 0:\n                    trimmed_sells.append(Order(product, o.price, int(-q)))\n                    remaining -= q\n\n            combined = trimmed_buys + trimmed_sells\n\n            if trimmed_buys and trimmed_sells:\n                min_sell_price = min(o.price for o in trimmed_sells)\n                combined = [o for o in combined\n                            if not (o.quantity > 0 and o.price >= min_sell_price)]\n\n            clean_orders[product] = combined\n\n        return clean_orders, 0, saved.dump()',
    'visors_v2': '"""\nvisors_v1.py — UV Visors basket trader (v1)\n\nCHANGES FROM v0:\n  - MAGENTA dropped. v0 MAGENTA finished at -$1.9k after plateauing then\n    bleeding. Drift +11.34% + ADF 0.94 (random walk) is the same toxic\n    combination that broke robots. Even with $14 spread, MM-only couldn\'t\n    overcome adverse selection on consistent drift.\n\nTIER 1 — Mean reversion + MM:\n  - UV_VISOR_RED      drift +9.38%, ADF 0.31\n  - UV_VISOR_YELLOW   drift -1.09%, ADF 0.86\n\nTIER 2 — MM-only:\n  - UV_VISOR_ORANGE   drift +9.63%, ADF 0.99 (clean +$9.7k in v0)\n\nDROPPED:\n  - UV_VISOR_AMBER    drift -25%\n  - UV_VISOR_MAGENTA  -$2k contribution in v0, no edge\n"""\n\nfrom datamodel import OrderDepth, TradingState, Order\nfrom dataclasses import dataclass\nfrom typing import List, Dict, Any\nimport json\nimport math\n\n\nPOSITION_LIMIT = 10\n\n\n# ============================================================================\n# State management\n# ============================================================================\n\nclass SavedState:\n    def __init__(self, data: Dict[str, Any] = None):\n        self.data = data or {}\n\n    @staticmethod\n    def load(s: str) -> "SavedState":\n        if not s:\n            return SavedState()\n        try:\n            return SavedState(json.loads(s))\n        except Exception:\n            return SavedState()\n\n    def get(self, key: str) -> Dict[str, Any]:\n        return self.data.setdefault(key, {})\n\n    def put(self, key: str, value: Dict[str, Any]):\n        self.data[key] = value\n\n    def dump(self) -> str:\n        return json.dumps(self.data)\n\n\n# ============================================================================\n# Utilities\n# ============================================================================\n\ndef best_bid_ask_mid(order_depth: OrderDepth):\n    if not order_depth.buy_orders or not order_depth.sell_orders:\n        return None, None, None\n    best_bid = max(order_depth.buy_orders.keys())\n    best_ask = min(order_depth.sell_orders.keys())\n    return best_bid, best_ask, (best_bid + best_ask) / 2.0\n\n\ndef take_liquidity_buy(product: str, order_depth: OrderDepth,\n                       max_qty: int) -> List[Order]:\n    orders = []\n    remaining = max_qty\n    for ask_price in sorted(order_depth.sell_orders.keys()):\n        if remaining <= 0:\n            break\n        ask_vol = abs(order_depth.sell_orders[ask_price])\n        fill = min(ask_vol, remaining)\n        if fill > 0:\n            orders.append(Order(product, ask_price, int(fill)))\n            remaining -= fill\n    return orders\n\n\ndef take_liquidity_sell(product: str, order_depth: OrderDepth,\n                        max_qty: int) -> List[Order]:\n    orders = []\n    remaining = max_qty\n    for bid_price in sorted(order_depth.buy_orders.keys(), reverse=True):\n        if remaining <= 0:\n            break\n        bid_vol = order_depth.buy_orders[bid_price]\n        fill = min(bid_vol, remaining)\n        if fill > 0:\n            orders.append(Order(product, bid_price, int(-fill)))\n            remaining -= fill\n    return orders\n\n\n# ============================================================================\n# EMA helpers\n# ============================================================================\n\ndef update_ema(state: dict, value: float, alpha: float):\n    if not state.get("initialized", False):\n        state["ema_mean"] = value\n        state["ema_var"] = state.get("ema_var", 1.0)\n        state["initialized"] = True\n        state["n_ticks"] = state.get("n_ticks", 0) + 1\n        state["last_value"] = value\n        return\n    old_mean = state["ema_mean"]\n    diff = value - old_mean\n    state["ema_var"] = (1 - alpha) * (state["ema_var"] + alpha * diff * diff)\n    state["ema_mean"] = old_mean + alpha * diff\n    state["n_ticks"] += 1\n    state["last_value"] = value\n\n\ndef compute_z_blended(state: dict, prior_mean: float, prior_std: float,\n                      alpha: float) -> float:\n    std_emp = math.sqrt(max(state["ema_var"], 1.0))\n    warmup_target = 3.0 / alpha\n    blend = min(1.0, state["n_ticks"] / warmup_target)\n    std = blend * std_emp + (1 - blend) * prior_std\n    mean = blend * state["ema_mean"] + (1 - blend) * prior_mean\n    if std <= 0:\n        return 0.0\n    return (state["last_value"] - mean) / std\n\n\ndef z_to_magnitude(z: float, z_min: float, z_full: float) -> int:\n    abs_z = abs(z)\n    if abs_z <= z_min:\n        return 0\n    if abs_z >= z_full:\n        return POSITION_LIMIT\n    scale = (abs_z - z_min) / (z_full - z_min)\n    return int(round(POSITION_LIMIT * scale))\n\n\ndef execute_leg_capped(product: str, depth: OrderDepth,\n                       best_bid: int, best_ask: int,\n                       target_pos: int, current_pos: int,\n                       cross_allowed: bool,\n                       my_orders: Dict[str, List[Order]],\n                       mm_base_size: int = 3,\n                       mm_max_deviation: int = 2,\n                       cross_min_gap: int = 5):\n    """Mean reversion + MM-at-target."""\n    buy_cap = max(0, POSITION_LIMIT - current_pos)\n    sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n    gap = target_pos - current_pos\n    bid_price = best_bid + 1 if (best_ask - best_bid) > 1 else best_bid\n    ask_price = best_ask - 1 if (best_ask - best_bid) > 1 else best_ask\n\n    my_buy_qty = 0\n    my_sell_qty = 0\n\n    if gap > 0:\n        qty_wanted = min(gap, buy_cap)\n        if cross_allowed and abs(gap) >= cross_min_gap and qty_wanted > 0:\n            taken = take_liquidity_buy(product, depth, qty_wanted)\n            taken_qty = sum(o.quantity for o in taken)\n            if taken_qty > buy_cap:\n                cap_remaining = buy_cap\n                fixed = []\n                for o in taken:\n                    if cap_remaining <= 0:\n                        break\n                    q = min(o.quantity, cap_remaining)\n                    fixed.append(Order(product, o.price, int(q)))\n                    cap_remaining -= q\n                taken = fixed\n                taken_qty = sum(o.quantity for o in taken)\n            my_orders.setdefault(product, []).extend(taken)\n            buy_cap -= taken_qty\n            qty_wanted -= taken_qty\n        if qty_wanted > 0 and buy_cap > 0:\n            my_buy_qty = min(qty_wanted, buy_cap)\n            buy_cap -= my_buy_qty\n    elif gap < 0:\n        qty_wanted = min(-gap, sell_cap)\n        if cross_allowed and abs(gap) >= cross_min_gap and qty_wanted > 0:\n            taken = take_liquidity_sell(product, depth, qty_wanted)\n            taken_qty = sum(-o.quantity for o in taken)\n            if taken_qty > sell_cap:\n                cap_remaining = sell_cap\n                fixed = []\n                for o in taken:\n                    if cap_remaining <= 0:\n                        break\n                    q = min(-o.quantity, cap_remaining)\n                    fixed.append(Order(product, o.price, int(-q)))\n                    cap_remaining -= q\n                taken = fixed\n                taken_qty = sum(-o.quantity for o in taken)\n            my_orders.setdefault(product, []).extend(taken)\n            sell_cap -= taken_qty\n            qty_wanted -= taken_qty\n        if qty_wanted > 0 and sell_cap > 0:\n            my_sell_qty = min(qty_wanted, sell_cap)\n            sell_cap -= my_sell_qty\n\n    target_drift_max = target_pos + mm_max_deviation\n    target_drift_min = target_pos - mm_max_deviation\n\n    mm_buy_room = target_drift_max - current_pos - my_buy_qty\n    mm_buy_qty = min(mm_base_size, max(0, mm_buy_room), buy_cap)\n\n    mm_sell_room = (current_pos - my_sell_qty) - target_drift_min\n    mm_sell_qty = min(mm_base_size, max(0, mm_sell_room), sell_cap)\n\n    total_buy_qty = my_buy_qty + mm_buy_qty\n    total_sell_qty = my_sell_qty + mm_sell_qty\n\n    max_total_buy = POSITION_LIMIT - current_pos\n    if total_buy_qty > max_total_buy:\n        total_buy_qty = max(0, max_total_buy)\n    max_total_sell = POSITION_LIMIT + current_pos\n    if total_sell_qty > max_total_sell:\n        total_sell_qty = max(0, max_total_sell)\n\n    if total_buy_qty > 0 and total_sell_qty > 0:\n        if bid_price >= ask_price:\n            if my_buy_qty > my_sell_qty:\n                total_sell_qty = 0\n            else:\n                total_buy_qty = 0\n\n    if total_buy_qty > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(bid_price), int(total_buy_qty))\n        )\n    if total_sell_qty > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(ask_price), int(-total_sell_qty))\n        )\n\n\ndef execute_mm_only(product: str, depth: OrderDepth,\n                    best_bid: int, best_ask: int,\n                    current_pos: int,\n                    my_orders: Dict[str, List[Order]],\n                    mm_base_size: int = 3,\n                    inventory_skew_max: int = 5):\n    """Pure MM with inventory skew — no directional signal."""\n    buy_cap = max(0, POSITION_LIMIT - current_pos)\n    sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n    bid_price = best_bid + 1 if (best_ask - best_bid) > 1 else best_bid\n    ask_price = best_ask - 1 if (best_ask - best_bid) > 1 else best_ask\n\n    pos_pct = max(-1.0, min(1.0, current_pos / inventory_skew_max))\n\n    buy_size = int(mm_base_size * (1.0 - max(0, pos_pct)))\n    sell_size = int(mm_base_size * (1.0 + min(0, pos_pct)))\n\n    buy_size = min(buy_size, buy_cap)\n    sell_size = min(sell_size, sell_cap)\n\n    if buy_size > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(bid_price), int(buy_size))\n        )\n    if sell_size > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(ask_price), int(-sell_size))\n        )\n\n\n# ============================================================================\n# Strategy\n# ============================================================================\n\n@dataclass\nclass MeanRevConfig:\n    product: str\n    prior_mean: float\n    prior_std: float\n    ema_alpha: float\n    z_entry_min: float\n    z_entry_full: float\n    z_take_threshold: float\n\n\n@dataclass\nclass MMOnlyConfig:\n    product: str\n    mm_base_size: int = 3\n    inventory_skew_max: int = 5\n\n\n# Tier 1: RED + YELLOW\nTIER_1_CONFIGS = [\n    MeanRevConfig(\n        product="UV_VISOR_RED",\n        prior_mean=11063.0,\n        prior_std=350.0,\n        ema_alpha=1.0 / 1500,\n        z_entry_min=0.3,\n        z_entry_full=1.0,\n        z_take_threshold=2.5,\n    ),\n    MeanRevConfig(\n        product="UV_VISOR_YELLOW",\n        prior_mean=10957.0,\n        prior_std=488.0,\n        ema_alpha=1.0 / 2500,\n        z_entry_min=0.3,\n        z_entry_full=1.0,\n        z_take_threshold=2.5,\n    ),\n]\n\n# Tier 2: only ORANGE (MAGENTA dropped)\nTIER_2_CONFIGS = [\n    MMOnlyConfig(product="UV_VISOR_ORANGE", mm_base_size=5, inventory_skew_max=7),\n]\n\n# DROPPED: AMBER (-25% drift), MAGENTA (-$2k v0)\n\n\nclass UVVisorStrategy:\n    name = "visors_v1"\n\n    @property\n    def products(self):\n        return ([c.product for c in TIER_1_CONFIGS]\n                + [c.product for c in TIER_2_CONFIGS])\n\n    def init_state(self, my_state: Dict[str, Any]):\n        my_state.setdefault("products", {})\n        for cfg in TIER_1_CONFIGS:\n            if cfg.product not in my_state["products"]:\n                my_state["products"][cfg.product] = {\n                    "ema_mean": cfg.prior_mean,\n                    "ema_var": cfg.prior_std ** 2,\n                    "initialized": False,\n                    "n_ticks": 0,\n                    "last_value": cfg.prior_mean,\n                }\n\n    def run(self, state: TradingState, my_state: Dict[str, Any],\n            my_orders: Dict[str, List[Order]]) -> None:\n        self.init_state(my_state)\n        for cfg in TIER_1_CONFIGS:\n            self._run_meanrev(state, my_state, my_orders, cfg)\n        for cfg in TIER_2_CONFIGS:\n            self._run_mm_only(state, my_orders, cfg)\n\n    def _run_meanrev(self, state: TradingState, my_state: Dict[str, Any],\n                     my_orders: Dict[str, List[Order]], cfg: MeanRevConfig):\n        if cfg.product not in state.order_depths:\n            return\n        depth = state.order_depths[cfg.product]\n        bb, ba, mid = best_bid_ask_mid(depth)\n        if mid is None:\n            return\n\n        p_state = my_state["products"][cfg.product]\n        update_ema(p_state, mid, cfg.ema_alpha)\n        z = compute_z_blended(p_state, cfg.prior_mean, cfg.prior_std, cfg.ema_alpha)\n        magnitude = z_to_magnitude(z, cfg.z_entry_min, cfg.z_entry_full)\n\n        if z > 0:\n            target_pos = -magnitude\n        elif z < 0:\n            target_pos = +magnitude\n        else:\n            target_pos = 0\n\n        cross_allowed = abs(z) >= cfg.z_take_threshold\n\n        execute_leg_capped(cfg.product, depth, bb, ba, target_pos,\n                           state.position.get(cfg.product, 0),\n                           cross_allowed, my_orders)\n\n        short = "RED" if "RED" in cfg.product else "YEL"\n        print(f"[uv:T1:{short}] mid={mid:.0f} ema={p_state[\'ema_mean\']:.0f} "\n              f"z={z:+.2f} mag={magnitude} tgt={target_pos} "\n              f"pos={state.position.get(cfg.product, 0)}")\n\n    def _run_mm_only(self, state: TradingState,\n                     my_orders: Dict[str, List[Order]], cfg: MMOnlyConfig):\n        if cfg.product not in state.order_depths:\n            return\n        depth = state.order_depths[cfg.product]\n        bb, ba, mid = best_bid_ask_mid(depth)\n        if mid is None:\n            return\n\n        execute_mm_only(cfg.product, depth, bb, ba,\n                        state.position.get(cfg.product, 0),\n                        my_orders, cfg.mm_base_size, cfg.inventory_skew_max)\n\n        print(f"[uv:T2:ORA] mid={mid:.0f} pos={state.position.get(cfg.product, 0)} "\n              f"bid={bb} ask={ba}")\n\n\n# ============================================================================\n# Trader\n# ============================================================================\n\nclass Trader:\n    def __init__(self):\n        self.strategies = [UVVisorStrategy()]\n\n    def run(self, state: TradingState):\n        saved = SavedState.load(state.traderData)\n        my_orders: Dict[str, List[Order]] = {}\n\n        for strat in self.strategies:\n            strat_state = saved.get(strat.name)\n            try:\n                strat.run(state, strat_state, my_orders)\n            except Exception as e:\n                print(f"[ERR strategy={strat.name}] {e}")\n            saved.put(strat.name, strat_state)\n\n        clean_orders = {}\n        for product, orders in my_orders.items():\n            current_pos = state.position.get(product, 0)\n            buy_cap = max(0, POSITION_LIMIT - current_pos)\n            sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n            buys = sorted([o for o in orders if o.quantity > 0], key=lambda o: o.price)\n            sells = sorted([o for o in orders if o.quantity < 0], key=lambda o: -o.price)\n\n            trimmed_buys = []\n            remaining = buy_cap\n            for o in buys:\n                if remaining <= 0:\n                    break\n                q = min(o.quantity, remaining)\n                if q > 0:\n                    trimmed_buys.append(Order(product, o.price, int(q)))\n                    remaining -= q\n\n            trimmed_sells = []\n            remaining = sell_cap\n            for o in sells:\n                if remaining <= 0:\n                    break\n                q = min(-o.quantity, remaining)\n                if q > 0:\n                    trimmed_sells.append(Order(product, o.price, int(-q)))\n                    remaining -= q\n\n            combined = trimmed_buys + trimmed_sells\n\n            if trimmed_buys and trimmed_sells:\n                min_sell_price = min(o.price for o in trimmed_sells)\n                combined = [o for o in combined\n                            if not (o.quantity > 0 and o.price >= min_sell_price)]\n\n            clean_orders[product] = combined\n\n        return clean_orders, 0, saved.dump()',
    'message_4': '"""\npebbles_v1.py — Pebbles basket trader (v1)\n\nCHANGES FROM v0:\n  - PEBBLES_M dropped from MM-only. Contributed only $1.9k in v0 with day 4\n    going to -$4k. Robots-style risk profile (drift+13%, ADF 0.76, no real\n    edge). Saving the position slot/risk.\n  - Spread EMA shortened from 1/500 to 1/200. v0 had a -$15k early drawdown\n    while EMA converged on the spread mean. Faster EMA should reduce this.\n\nTIER 1 — Spread trade (basket arb):\n  - L-XL spread  (the cash cow: $60k combined L+XL in v0 backtest)\n\nTIER 2 — Solo mean reverter:\n  - PEBBLES_S    (best ADF in dataset, $13.4k in v0)\n\nDROPPED:\n  - PEBBLES_XS   drift -34%\n  - PEBBLES_M    weak edge, dragged down day 4\n"""\n\nfrom datamodel import OrderDepth, TradingState, Order\nfrom dataclasses import dataclass\nfrom typing import List, Dict, Any\nimport json\nimport math\n\n\nPOSITION_LIMIT = 10\n\n\n# ============================================================================\n# State management\n# ============================================================================\n\nclass SavedState:\n    def __init__(self, data: Dict[str, Any] = None):\n        self.data = data or {}\n\n    @staticmethod\n    def load(s: str) -> "SavedState":\n        if not s:\n            return SavedState()\n        try:\n            return SavedState(json.loads(s))\n        except Exception:\n            return SavedState()\n\n    def get(self, key: str) -> Dict[str, Any]:\n        return self.data.setdefault(key, {})\n\n    def put(self, key: str, value: Dict[str, Any]):\n        self.data[key] = value\n\n    def dump(self) -> str:\n        return json.dumps(self.data)\n\n\n# ============================================================================\n# Utilities\n# ============================================================================\n\ndef best_bid_ask_mid(order_depth: OrderDepth):\n    if not order_depth.buy_orders or not order_depth.sell_orders:\n        return None, None, None\n    best_bid = max(order_depth.buy_orders.keys())\n    best_ask = min(order_depth.sell_orders.keys())\n    return best_bid, best_ask, (best_bid + best_ask) / 2.0\n\n\ndef take_liquidity_buy(product: str, order_depth: OrderDepth,\n                       max_qty: int) -> List[Order]:\n    orders = []\n    remaining = max_qty\n    for ask_price in sorted(order_depth.sell_orders.keys()):\n        if remaining <= 0:\n            break\n        ask_vol = abs(order_depth.sell_orders[ask_price])\n        fill = min(ask_vol, remaining)\n        if fill > 0:\n            orders.append(Order(product, ask_price, int(fill)))\n            remaining -= fill\n    return orders\n\n\ndef take_liquidity_sell(product: str, order_depth: OrderDepth,\n                        max_qty: int) -> List[Order]:\n    orders = []\n    remaining = max_qty\n    for bid_price in sorted(order_depth.buy_orders.keys(), reverse=True):\n        if remaining <= 0:\n            break\n        bid_vol = order_depth.buy_orders[bid_price]\n        fill = min(bid_vol, remaining)\n        if fill > 0:\n            orders.append(Order(product, bid_price, int(-fill)))\n            remaining -= fill\n    return orders\n\n\n# ============================================================================\n# EMA helpers\n# ============================================================================\n\ndef update_ema(state: dict, value: float, alpha: float):\n    if not state.get("initialized", False):\n        state["ema_mean"] = value\n        state["ema_var"] = state.get("ema_var", 1.0)\n        state["initialized"] = True\n        state["n_ticks"] = state.get("n_ticks", 0) + 1\n        state["last_value"] = value\n        return\n    old_mean = state["ema_mean"]\n    diff = value - old_mean\n    state["ema_var"] = (1 - alpha) * (state["ema_var"] + alpha * diff * diff)\n    state["ema_mean"] = old_mean + alpha * diff\n    state["n_ticks"] += 1\n    state["last_value"] = value\n\n\ndef compute_z_blended(state: dict, prior_mean: float, prior_std: float,\n                      alpha: float) -> float:\n    std_emp = math.sqrt(max(state["ema_var"], 1.0))\n    warmup_target = 3.0 / alpha\n    blend = min(1.0, state["n_ticks"] / warmup_target)\n    std = blend * std_emp + (1 - blend) * prior_std\n    mean = blend * state["ema_mean"] + (1 - blend) * prior_mean\n    if std <= 0:\n        return 0.0\n    return (state["last_value"] - mean) / std\n\n\ndef z_to_magnitude(z: float, z_min: float, z_full: float) -> int:\n    abs_z = abs(z)\n    if abs_z <= z_min:\n        return 0\n    if abs_z >= z_full:\n        return POSITION_LIMIT\n    scale = (abs_z - z_min) / (z_full - z_min)\n    return int(round(POSITION_LIMIT * scale))\n\n\ndef execute_leg_capped(product: str, depth: OrderDepth,\n                       best_bid: int, best_ask: int,\n                       target_pos: int, current_pos: int,\n                       cross_allowed: bool,\n                       my_orders: Dict[str, List[Order]],\n                       mm_base_size: int = 3,\n                       mm_max_deviation: int = 2,\n                       cross_min_gap: int = 5):\n    """Mean reversion + MM-at-target."""\n    buy_cap = max(0, POSITION_LIMIT - current_pos)\n    sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n    gap = target_pos - current_pos\n    bid_price = best_bid + 1 if (best_ask - best_bid) > 1 else best_bid\n    ask_price = best_ask - 1 if (best_ask - best_bid) > 1 else best_ask\n\n    my_buy_qty = 0\n    my_sell_qty = 0\n\n    if gap > 0:\n        qty_wanted = min(gap, buy_cap)\n        if cross_allowed and abs(gap) >= cross_min_gap and qty_wanted > 0:\n            taken = take_liquidity_buy(product, depth, qty_wanted)\n            taken_qty = sum(o.quantity for o in taken)\n            if taken_qty > buy_cap:\n                cap_remaining = buy_cap\n                fixed = []\n                for o in taken:\n                    if cap_remaining <= 0:\n                        break\n                    q = min(o.quantity, cap_remaining)\n                    fixed.append(Order(product, o.price, int(q)))\n                    cap_remaining -= q\n                taken = fixed\n                taken_qty = sum(o.quantity for o in taken)\n            my_orders.setdefault(product, []).extend(taken)\n            buy_cap -= taken_qty\n            qty_wanted -= taken_qty\n        if qty_wanted > 0 and buy_cap > 0:\n            my_buy_qty = min(qty_wanted, buy_cap)\n            buy_cap -= my_buy_qty\n    elif gap < 0:\n        qty_wanted = min(-gap, sell_cap)\n        if cross_allowed and abs(gap) >= cross_min_gap and qty_wanted > 0:\n            taken = take_liquidity_sell(product, depth, qty_wanted)\n            taken_qty = sum(-o.quantity for o in taken)\n            if taken_qty > sell_cap:\n                cap_remaining = sell_cap\n                fixed = []\n                for o in taken:\n                    if cap_remaining <= 0:\n                        break\n                    q = min(-o.quantity, cap_remaining)\n                    fixed.append(Order(product, o.price, int(-q)))\n                    cap_remaining -= q\n                taken = fixed\n                taken_qty = sum(-o.quantity for o in taken)\n            my_orders.setdefault(product, []).extend(taken)\n            sell_cap -= taken_qty\n            qty_wanted -= taken_qty\n        if qty_wanted > 0 and sell_cap > 0:\n            my_sell_qty = min(qty_wanted, sell_cap)\n            sell_cap -= my_sell_qty\n\n    target_drift_max = target_pos + mm_max_deviation\n    target_drift_min = target_pos - mm_max_deviation\n\n    mm_buy_room = target_drift_max - current_pos - my_buy_qty\n    mm_buy_qty = min(mm_base_size, max(0, mm_buy_room), buy_cap)\n\n    mm_sell_room = (current_pos - my_sell_qty) - target_drift_min\n    mm_sell_qty = min(mm_base_size, max(0, mm_sell_room), sell_cap)\n\n    total_buy_qty = my_buy_qty + mm_buy_qty\n    total_sell_qty = my_sell_qty + mm_sell_qty\n\n    max_total_buy = POSITION_LIMIT - current_pos\n    if total_buy_qty > max_total_buy:\n        total_buy_qty = max(0, max_total_buy)\n    max_total_sell = POSITION_LIMIT + current_pos\n    if total_sell_qty > max_total_sell:\n        total_sell_qty = max(0, max_total_sell)\n\n    if total_buy_qty > 0 and total_sell_qty > 0:\n        if bid_price >= ask_price:\n            if my_buy_qty > my_sell_qty:\n                total_sell_qty = 0\n            else:\n                total_buy_qty = 0\n\n    if total_buy_qty > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(bid_price), int(total_buy_qty))\n        )\n    if total_sell_qty > 0:\n        my_orders.setdefault(product, []).append(\n            Order(product, int(ask_price), int(-total_sell_qty))\n        )\n\n\n# ============================================================================\n# Strategy configs\n# ============================================================================\n\n@dataclass\nclass SpreadConfig:\n    leg_a: str\n    leg_b: str\n    prior_mean: float\n    prior_std: float\n    ema_alpha: float\n    z_entry_min: float\n    z_entry_full: float\n    z_take_threshold: float\n\n\n@dataclass\nclass SoloConfig:\n    product: str\n    prior_mean: float\n    prior_std: float\n    ema_alpha: float\n    z_entry_min: float\n    z_entry_full: float\n    z_take_threshold: float\n\n\n# Tier 1: L-XL spread (faster EMA than v0)\nSPREAD_CONFIGS = [\n    SpreadConfig(\n        leg_a="PEBBLES_L",\n        leg_b="PEBBLES_XL",\n        prior_mean=-3261.0,\n        prior_std=250.0,\n        ema_alpha=1.0 / 100,   # was 1/500 in v0 — faster to reduce early DD\n        z_entry_min=0.3,\n        z_entry_full=1.0,\n        z_take_threshold=2.0,\n    ),\n]\n\n# Tier 2: PEBBLES_S solo\nSOLO_CONFIGS = [\n    SoloConfig(\n        product="PEBBLES_S",\n        prior_mean=9197.0,\n        prior_std=300.0,\n        ema_alpha=1.0 / 1000,\n        z_entry_min=0.3,\n        z_entry_full=1.0,\n        z_take_threshold=2.5,\n    ),\n]\n\n\nclass PebblesStrategy:\n    name = "pebbles_v1"\n\n    @property\n    def products(self):\n        prods = set()\n        for cfg in SPREAD_CONFIGS:\n            prods.add(cfg.leg_a)\n            prods.add(cfg.leg_b)\n        for cfg in SOLO_CONFIGS:\n            prods.add(cfg.product)\n        return list(prods)\n\n    def init_state(self, my_state: Dict[str, Any]):\n        my_state.setdefault("spreads", {})\n        my_state.setdefault("solos", {})\n\n        for cfg in SPREAD_CONFIGS:\n            key = f"{cfg.leg_a}_{cfg.leg_b}"\n            if key not in my_state["spreads"]:\n                my_state["spreads"][key] = {\n                    "ema_mean": cfg.prior_mean,\n                    "ema_var": cfg.prior_std ** 2,\n                    "initialized": False,\n                    "n_ticks": 0,\n                    "last_value": cfg.prior_mean,\n                }\n\n        for cfg in SOLO_CONFIGS:\n            if cfg.product not in my_state["solos"]:\n                my_state["solos"][cfg.product] = {\n                    "ema_mean": cfg.prior_mean,\n                    "ema_var": cfg.prior_std ** 2,\n                    "initialized": False,\n                    "n_ticks": 0,\n                    "last_value": cfg.prior_mean,\n                }\n\n    def run(self, state: TradingState, my_state: Dict[str, Any],\n            my_orders: Dict[str, List[Order]]) -> None:\n        self.init_state(my_state)\n        for cfg in SPREAD_CONFIGS:\n            self._run_spread(state, my_state, my_orders, cfg)\n        for cfg in SOLO_CONFIGS:\n            self._run_solo(state, my_state, my_orders, cfg)\n\n    def _run_spread(self, state: TradingState, my_state: Dict[str, Any],\n                    my_orders: Dict[str, List[Order]], cfg: SpreadConfig):\n        if cfg.leg_a not in state.order_depths or cfg.leg_b not in state.order_depths:\n            return\n        depth_a = state.order_depths[cfg.leg_a]\n        depth_b = state.order_depths[cfg.leg_b]\n        bb_a, ba_a, mid_a = best_bid_ask_mid(depth_a)\n        bb_b, ba_b, mid_b = best_bid_ask_mid(depth_b)\n        if mid_a is None or mid_b is None:\n            return\n\n        spread = mid_a - mid_b\n        key = f"{cfg.leg_a}_{cfg.leg_b}"\n        s_state = my_state["spreads"][key]\n        update_ema(s_state, spread, cfg.ema_alpha)\n        z = compute_z_blended(s_state, cfg.prior_mean, cfg.prior_std, cfg.ema_alpha)\n        magnitude = z_to_magnitude(z, cfg.z_entry_min, cfg.z_entry_full)\n\n        if z > 0:\n            target_a = -magnitude\n            target_b = +magnitude\n        elif z < 0:\n            target_a = +magnitude\n            target_b = -magnitude\n        else:\n            target_a = 0\n            target_b = 0\n\n        cross_allowed = abs(z) >= cfg.z_take_threshold\n\n        execute_leg_capped(cfg.leg_a, depth_a, bb_a, ba_a, target_a,\n                           state.position.get(cfg.leg_a, 0),\n                           cross_allowed, my_orders)\n        execute_leg_capped(cfg.leg_b, depth_b, bb_b, ba_b, target_b,\n                           state.position.get(cfg.leg_b, 0),\n                           cross_allowed, my_orders)\n\n        a_short = cfg.leg_a.replace("PEBBLES_", "")\n        b_short = cfg.leg_b.replace("PEBBLES_", "")\n        print(f"[pb:T1:{a_short}-{b_short}] spread={spread:.0f} ema={s_state[\'ema_mean\']:.0f} "\n              f"z={z:+.2f} mag={magnitude} tgt_a={target_a} tgt_b={target_b} "\n              f"pos_a={state.position.get(cfg.leg_a, 0)} pos_b={state.position.get(cfg.leg_b, 0)}")\n\n    def _run_solo(self, state: TradingState, my_state: Dict[str, Any],\n                  my_orders: Dict[str, List[Order]], cfg: SoloConfig):\n        if cfg.product not in state.order_depths:\n            return\n        depth = state.order_depths[cfg.product]\n        bb, ba, mid = best_bid_ask_mid(depth)\n        if mid is None:\n            return\n\n        p_state = my_state["solos"][cfg.product]\n        update_ema(p_state, mid, cfg.ema_alpha)\n        z = compute_z_blended(p_state, cfg.prior_mean, cfg.prior_std, cfg.ema_alpha)\n        magnitude = z_to_magnitude(z, cfg.z_entry_min, cfg.z_entry_full)\n\n        if z > 0:\n            target_pos = -magnitude\n        elif z < 0:\n            target_pos = +magnitude\n        else:\n            target_pos = 0\n\n        cross_allowed = abs(z) >= cfg.z_take_threshold\n\n        execute_leg_capped(cfg.product, depth, bb, ba, target_pos,\n                           state.position.get(cfg.product, 0),\n                           cross_allowed, my_orders)\n\n        short = cfg.product.replace("PEBBLES_", "")\n        print(f"[pb:T2:{short}] mid={mid:.0f} ema={p_state[\'ema_mean\']:.0f} "\n              f"z={z:+.2f} mag={magnitude} tgt={target_pos} "\n              f"pos={state.position.get(cfg.product, 0)}")\n\n\n# ============================================================================\n# Trader\n# ============================================================================\n\nclass Trader:\n    def __init__(self):\n        self.strategies = [PebblesStrategy()]\n\n    def run(self, state: TradingState):\n        saved = SavedState.load(state.traderData)\n        my_orders: Dict[str, List[Order]] = {}\n\n        for strat in self.strategies:\n            strat_state = saved.get(strat.name)\n            try:\n                strat.run(state, strat_state, my_orders)\n            except Exception as e:\n                print(f"[ERR strategy={strat.name}] {e}")\n            saved.put(strat.name, strat_state)\n\n        clean_orders = {}\n        for product, orders in my_orders.items():\n            current_pos = state.position.get(product, 0)\n            buy_cap = max(0, POSITION_LIMIT - current_pos)\n            sell_cap = max(0, POSITION_LIMIT + current_pos)\n\n            buys = sorted([o for o in orders if o.quantity > 0], key=lambda o: o.price)\n            sells = sorted([o for o in orders if o.quantity < 0], key=lambda o: -o.price)\n\n            trimmed_buys = []\n            remaining = buy_cap\n            for o in buys:\n                if remaining <= 0:\n                    break\n                q = min(o.quantity, remaining)\n                if q > 0:\n                    trimmed_buys.append(Order(product, o.price, int(q)))\n                    remaining -= q\n\n            trimmed_sells = []\n            remaining = sell_cap\n            for o in sells:\n                if remaining <= 0:\n                    break\n                q = min(-o.quantity, remaining)\n                if q > 0:\n                    trimmed_sells.append(Order(product, o.price, int(-q)))\n                    remaining -= q\n\n            combined = trimmed_buys + trimmed_sells\n\n            if trimmed_buys and trimmed_sells:\n                min_sell_price = min(o.price for o in trimmed_sells)\n                combined = [o for o in combined\n                            if not (o.quantity > 0 and o.price >= min_sell_price)]\n\n            clean_orders[product] = combined\n\n        return clean_orders, 0, saved.dump()',
}

def _load_trader_class(name: str, source: str):
    namespace = {"__name__": f"_embedded_{name}"}
    exec(compile(source, f"<{name}>", "exec"), namespace)
    return namespace["Trader"]

TRADER_CLASSES = {
    name: _load_trader_class(name, source)
    for name, source in MODULE_SOURCES.items()
}

class _StateView:
    def __init__(self, state: TradingState, trader_data: str):
        self.traderData = trader_data
        self.timestamp = state.timestamp
        self.listings = state.listings
        self.order_depths = state.order_depths
        self.own_trades = state.own_trades
        self.market_trades = state.market_trades
        self.position = state.position
        self.observations = state.observations
        if hasattr(state, "profit_and_loss"):
            self.profit_and_loss = state.profit_and_loss

def _load_parent_state(raw: str) -> dict:
    if not raw:
        return {}
    try:
        value = json.loads(raw)
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}

def _merge_orders(base: Dict[str, List[Order]], extra: Dict[str, List[Order]]):
    if not extra:
        return
    for product, orders in extra.items():
        if orders:
            base.setdefault(product, []).extend(orders)

def _cap_orders(orders_by_product: Dict[str, List[Order]], positions: dict):
    clean = {}
    for product, orders in orders_by_product.items():
        current_pos = positions.get(product, 0)
        buy_cap = max(0, POSITION_LIMIT - current_pos)
        sell_cap = max(0, POSITION_LIMIT + current_pos)
        buys = sorted([o for o in orders if o.quantity > 0], key=lambda o: o.price, reverse=True)
        sells = sorted([o for o in orders if o.quantity < 0], key=lambda o: o.price)
        trimmed = []
        remaining = buy_cap
        for order in buys:
            if remaining <= 0:
                break
            qty = min(order.quantity, remaining)
            if qty > 0:
                trimmed.append(Order(product, order.price, int(qty)))
                remaining -= qty
        remaining = sell_cap
        for order in sells:
            if remaining <= 0:
                break
            qty = min(-order.quantity, remaining)
            if qty > 0:
                trimmed.append(Order(product, order.price, int(-qty)))
                remaining -= qty
        if trimmed:
            clean[product] = trimmed
    return clean

class Trader:
    def __init__(self):
        self.traders = {name: cls() for name, cls in TRADER_CLASSES.items()}

    def run(self, state: TradingState):
        parent_state = _load_parent_state(state.traderData)
        merged_orders: Dict[str, List[Order]] = {}
        conversions = 0
        next_state = {}
        for name, trader in self.traders.items():
            child_data = parent_state.get(name, "")
            view = _StateView(state, child_data if isinstance(child_data, str) else "")
            try:
                child_orders, child_conversions, new_child_data = trader.run(view)
                _merge_orders(merged_orders, child_orders)
                conversions += child_conversions or 0
                next_state[name] = new_child_data or ""
            except Exception as e:
                print(f"[ERR final:{name}] {e}")
                next_state[name] = child_data if isinstance(child_data, str) else ""
        return _cap_orders(merged_orders, state.position), conversions, json.dumps(next_state)
